import { defineComponent } from 'vue';

export default defineComponent({
    name: 'MenuItem',
    props: {
        visible: {
            type: Boolean,
            default: true
        },
        icon: {
            type: String,
            required: true
        },
        text: {
            type: String,
            required: true
        },
        toggled: {
            type: Boolean,
            default: false
        },
        showNotification: {
            type: Boolean,
            default: false
        },
        notificationText: {
            type: String,
            default: ''
        }
    },
    methods: {
        onClick() {
            this.$emit('onClick');
        }
    }
});
